payload, err := json.Marshal(graph)
if err != nil { return err }
_, err = db.Exec(`UPDATE diagrams SET graph = $1 WHERE id = $2`, payload, id)
// read back:
var raw []byte
if err := db.QueryRow(`SELECT graph FROM diagrams WHERE id = $1`, id).Scan(&raw); err != nil { return err }
return json.Unmarshal(raw, &graph)

